    ;(campaign_ref01_data_up0 as any)[campaign_ref01_markdef_up0.name] = campaign_ref01_markdef_up0.value

    const campaign_ref01_resdata_up0 = (await campaign_ref01_ent.update(campaign_ref01_data_up0)).data()
